import { DataWidget } from './DataWidget.js';
import { dateOffset, COLORS } from './WorkspaceStore.js';
import { lineChart, barChart } from './charts.js';
const TITLES={trend:'Как меняется твой ритм',distribution:'Куда уходит внимание',heatmap:'Календарь постоянства',balance:'Баланс проектов'};
export class AnalyticsWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:TITLES[config.type]||'Аналитика'},dashboard);this.period=14;}
  update(){const header=this.element('div','widget-subheading');header.append(this.element('span','subtle-text',this.type==='heatmap'?'Отметки привычек за 12 недель':this.type==='distribution'?'Фокус-сессии по категориям':this.type==='balance'?'Завершённые задачи по проектам':'Минуты сосредоточенной работы'));if(this.type==='trend')header.append(this.select('period','Период графика',[['7','7 дней'],['14','14 дней'],['30','30 дней']],String(this.period)));this.content.replaceChildren(header);if(this.type==='trend')this.renderTrend();if(this.type==='distribution')this.renderDistribution();if(this.type==='heatmap')this.renderHeatmap();if(this.type==='balance')this.renderBalance();}
  change(event){if(event.target.name==='period'){this.period=Number(event.target.value);this.update();}}
  renderTrend(){const days=Array.from({length:this.period},(_,i)=>dateOffset(i-this.period+1));const values=days.map(date=>this.dashboard.sessions.filter(s=>s.date===date).reduce((sum,s)=>sum+s.minutes,0));const total=values.reduce((a,b)=>a+b,0);const summary=this.element('div','chart-summary');const value=this.element('strong','',total);value.append(this.element('small','','мин за период'));summary.append(value,this.element('span','soft-badge',`${Math.round(total/this.period)} мин в среднем`));this.content.append(summary,lineChart(values,days.map(date=>new Date(`${date}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'short'}))),this.element('p','chart-note','Завершённые сессии учитываются в день окончания.'));}
  renderDistribution(){const categories=['Творчество','Развитие','Личное'];const values=categories.map(category=>this.dashboard.sessions.filter(s=>(s.category||'Личное')===category).reduce((sum,s)=>sum+s.minutes,0));const total=values.reduce((a,b)=>a+b,0);const layout=this.element('div','donut-layout');const donut=this.element('div','donut');let start=0;const stops=values.map((value,i)=>{const end=start+(total?value/total*100:0);const segment=`${COLORS[i]} ${start}% ${end}%`;start=end;return segment;});donut.style.background=total?`conic-gradient(${stops.join(',')})`:'#eeeaf3';donut.setAttribute('role','img');donut.setAttribute('aria-label',categories.map((c,i)=>`${c}: ${values[i]} минут`).join('; '));const center=this.element('div','donut-center');center.append(this.element('strong','',Math.round(total/60*10)/10),this.element('small','','часов фокуса'));donut.append(center);const legend=this.element('div','donut-legend');categories.forEach((category,i)=>{const row=this.element('div');const color=this.element('i');color.style.background=COLORS[i];row.append(color,this.element('span','',category),this.element('strong','',`${total?Math.round(values[i]/total*100):0}%`));legend.append(row);});layout.append(donut,legend);this.content.append(layout,this.element('p','chart-note','Категория выбирается перед запуском таймера.'));}
  renderHeatmap(){const heatmap=this.element('div','heatmap');heatmap.setAttribute('role','img');const today=new Date();const monday=new Date(today);monday.setDate(monday.getDate()-((monday.getDay()+6)%7)-77);const weeks=[];for(let week=0;week<12;week++){const column=this.element('div','heatmap-column');for(let day=0;day<7;day++){const date=dateOffset(week*7+day,monday);const count=this.store.data.habits.filter(h=>h.days.includes(date)).length;const cell=this.element('span',`heatmap-cell level-${Math.min(4,count)}`);if(date>dateOffset(0))cell.classList.add('future');cell.title=`${date}: ${count} привычек`;column.append(cell);weeks.push(`${date}: ${count}`);}heatmap.append(column);}heatmap.setAttribute('aria-label',`Отметки привычек по дням. ${weeks.join('; ')}`);const legend=this.element('div','heatmap-legend');legend.append(this.element('span','','Меньше'));for(let i=0;i<=4;i++)legend.append(this.element('i',`heatmap-cell level-${i}`));legend.append(this.element('span','','Больше'));this.content.append(heatmap,legend,this.element('p','chart-note','Постоянство складывается из маленьких повторений.'));}
  renderBalance(){const list=this.element('div','balance-list');for(const project of this.store.data.projects){const progress=this.store.progress(project.id);const row=this.element('div','balance-row');const top=this.element('div');top.append(this.element('strong','',project.name),this.element('span','',`${progress.done} из ${progress.total} · ${progress.percent}%`));const bar=this.element('div','progress-track');const fill=this.element('i');fill.style.width=`${progress.percent}%`;fill.style.background=COLORS[project.color];bar.append(fill);row.append(top,bar);list.append(row);}this.content.append(this.store.data.projects.length?list:this.empty('Создай проект и добавь задачи — здесь появится его прогресс.'));}
}
